formula.expression:
if(prop("Parent Event").length() == 0,
  prop("Own Sale ID"),
  prop("Parent Sale ID")
)

lets(
  /* Get coaches directly from Coaches relation */
  eventCoaches, {{notion:block_property:V%3B_L:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}},
  myCoach, eventCoaches.first(),
  myScheduled, {{notion:block_property:mwoF:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}},
  myStatus, {{notion:block_property:cUBI:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}},

  /* Skip if no coach assigned or no schedule set */
  if(empty(myCoach) or empty(myScheduled) or myStatus == "Cancelled",
    "",
    lets(
      /* Get all events where this coach is assigned */
      coachEvents, myCoach.{{notion:block_property:W%3C%3C%3A:261afdfb-c3c7-81f8-8cda-000ba9e72403:728afdfb-c3c7-816d-b8e3-0003a3b6442c}},

      /* Find events at the same scheduled time that aren't cancelled */
      conflictingEvents, coachEvents.filter(
        current.{{notion:block_property:mwoF:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}} == myScheduled and
        current.{{notion:block_property:cUBI:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}} != "Cancelled"
      ),

      /* Check sub-events for coach conflicts */
      subEventCoaches, {{notion:block_property:BJGf:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}}
        .map(current.{{notion:block_property:V%3B_L:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}})
        .flat(),

      /* Get first sub-event coach */
      subCoach, subEventCoaches.first(),

      /* Check sub-event coach's other events */
      subCoachConflicts, if(empty(subCoach), 0,
        subCoach.{{notion:block_property:W%3C%3C%3A:261afdfb-c3c7-81f8-8cda-000ba9e72403:728afdfb-c3c7-816d-b8e3-0003a3b6442c}}.filter(
          current.{{notion:block_property:mwoF:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}} == myScheduled and
          current.{{notion:block_property:cUBI:00000000-0000-0000-0000-000000000000:728afdfb-c3c7-816d-b8e3-0003a3b6442c}} != "Cancelled"
        ).length()
      ),

      /* Return availability status */
      ifs(
        conflictingEvents.length() > 1, "⚠️ Conflict (" + format(conflictingEvents.length() - 1) + " other)",
        subCoachConflicts > 1, "⚠️ Sub-coach conflict",
        "✅ Available"
      )
    )
  )
)

lets(
  /* Combine all people from the three permission properties */
  allPeople, concat(
    prop("Can Edit"),
    prop("Can Comment"),
    prop("Can View")
  ),
  /* Extract display names from all people and groups */
  allNames, allPeople.map(current.name()),
  /* Check for specific groups in priority order */
  ifs(
    allNames.includes("Team"), "Team",
    allNames.includes("Leadership"), "Leadership",
    allNames.includes("Owners"), "Owners",
    "Admin"
  )
)
